Lemma vis_ok_1RB1RD_0LC0RD_1LC1LA_0LA0RB : forall r t, ~ In t pins_1RB1RD_0LC0RD_1LC1LA_0LA0RB -> 0 < r ->
  r < 2 + 1 ->
